import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"編年史簡表","description":"","frontmatter":{},"headers":[],"relativePath":"ja/93-编年史简表.md","filePath":"ja/93-编年史简表.md","lastUpdated":null}'),h={name:"ja/93-编年史简表.md"};function l(o,t,i,b,n,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="編年史簡表" tabindex="-1">編年史簡表 <a class="header-anchor" href="#編年史簡表" aria-label="Permalink to &quot;編年史簡表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>93</td></tr><tr><td>所属モジュール</td><td>付録と参考資料</td></tr><tr><td>キーワード</td><td>編年史、紀元区分、重大事件、歴史ノード、恒元宙</td></tr></tbody></table><h2 id="一、編年史の説明" tabindex="-1">一、編年史の説明 <a class="header-anchor" href="#一、編年史の説明" aria-label="Permalink to &quot;一、編年史の説明&quot;">​</a></h2><p>本簡表は恒元宙標準時間を基準とし、紀元順にアンカー共生文明の発展過程における重大な歴史事件と重要なノードを記録する。時間の幅は前アンカー時代の太古の時期から、星間共生時代の未来展望まで及ぶ。各紀元には開始終了時間、時代の特徴、重大事件が記載されている。本簡表は高度に濃縮された歴史索引であり、各紀元の詳細な歴史については文書70-79の専門記述を参照されたい。</p><h2 id="二、紀元区分総覧" tabindex="-1">二、紀元区分総覧 <a class="header-anchor" href="#二、紀元区分総覧" aria-label="Permalink to &quot;二、紀元区分総覧&quot;">​</a></h2><table tabindex="0"><thead><tr><th>紀元番号</th><th>紀元名称</th><th>開始終了時間（恒元宙標準年）</th><th>持続時間</th><th>核心的特徴</th></tr></thead><tbody><tr><td>第一紀元</td><td>前アンカー時代</td><td>約-100億年から-1万年</td><td>約100億年</td><td>略奪式修練体系が主導、文明の興亡循環</td></tr><tr><td>第二紀元</td><td>アンカー覚醒紀元</td><td>-1万年から-1000年</td><td>約9000年</td><td>アンカーメカニズムが発見され初步的に応用される</td></tr><tr><td>第三紀元</td><td>共生体系確立期</td><td>-1000年から-100年</td><td>約900年</td><td>アンカー共生文明の制度枠組みが次第に確立される</td></tr><tr><td>第四紀元</td><td>三百套体系開放期</td><td>-100年から-50年</td><td>約50年</td><td>三百套本源修練体系が全面的に開放される</td></tr><tr><td>第五紀元</td><td>20%活性化戦略期</td><td>-50年から元年</td><td>約50年</td><td>20%の衆生が活性化され位面至高強者となる</td></tr><tr><td>第六紀元</td><td>首次昇維紀元</td><td>元年から100年</td><td>100年</td><td>共生文明が初めて段階的昇維を実現する</td></tr><tr><td>第七紀元</td><td>万族共和紀元</td><td>100年から500年</td><td>400年</td><td>万族共和が正式に成立、跨種族融合が深化する</td></tr><tr><td>第八紀元</td><td>跨位面探索紀元</td><td>500年から2000年</td><td>1500年</td><td>大規模な跨位面探索と考古活動が展開される</td></tr><tr><td>第九紀元</td><td>星間共生時代</td><td>2000年から未来</td><td>進行中</td><td>宇宙級共生ネットワークが建成、全体的昇維が推進される</td></tr></tbody></table><p>注：「元年」とはアンカー共生文明が正式に樹立を宣言した年を指し、歴史紀年の分界点とする。</p><h2 id="三、前アンカー時代-約-100億年から-1万年" tabindex="-1">三、前アンカー時代（約-100億年から-1万年） <a class="header-anchor" href="#三、前アンカー時代-約-100億年から-1万年" aria-label="Permalink to &quot;三、前アンカー時代（約-100億年から-1万年）&quot;">​</a></h2><p>前アンカー時代は恒元宙の歴史上最も長い紀元であり、約百億年持続した。この時代の核心的特徴は略奪式修練体系が宇宙を主導し、文明が「興起—鼎盛—略奪—崩壊」の循環の中で絶えず往復したことである。</p><table tabindex="0"><thead><tr><th>時間ノード</th><th>重大事件</th></tr></thead><tbody><tr><td>約-100億年</td><td>恒元宙の法則ネットワークが安定し、最初の物質位面が形成され、宇宙が居住可能な状態に入る</td></tr><tr><td>約-80億年</td><td>最初の知的生命が複数の物質位面で誕生し、原始修練体系が萌芽し始める</td></tr><tr><td>約-50億年</td><td>略奪式修練体系が次第に主流となり、強者が弱者を飲み込むことで急速な進化を実現する</td></tr><tr><td>約-30億年</td><td>初の宇宙級略奪戦争が勃発し、複数の星域の文明が壊滅的な打撃を受ける</td></tr><tr><td>約-10億年</td><td>略奪式体系の弊害が現れ始め、宇宙全体のエントロピー増加が加速し、修練資源が日に日に枯渇する</td></tr><tr><td>約-5億年</td><td>略奪式体系を反省する最初の思想家が出現し、共生思想の萌芽が育まれ始める</td></tr><tr><td>約-1億年</td><td>複数の星域で小規模な共生実験的文明が出現するが、いずれも略奪式文明によって破壊される</td></tr><tr><td>約-100万年</td><td>宇宙全体が「大衰退期」に入り、文明数と修練レベルの両方が歴史的最低点に低下する</td></tr><tr><td>約-1万年</td><td>第一位面のある修練者が長期の修練の中で偶然法則ネットワーク中の安定ノードを感知し、アンカーメカニズムが初めて発見される</td></tr></tbody></table><h2 id="四、アンカー覚醒紀元-1万年から-1000年" tabindex="-1">四、アンカー覚醒紀元（-1万年から-1000年） <a class="header-anchor" href="#四、アンカー覚醒紀元-1万年から-1000年" aria-label="Permalink to &quot;四、アンカー覚醒紀元（-1万年から-1000年）&quot;">​</a></h2><p>アンカー覚醒紀元はアンカーメカニズムが発見から初步的応用に至るまでの過渡期である。この紀元の核心的特徴はアンカー技術の次第なる成熟と共生思想の伝播である。</p><table tabindex="0"><thead><tr><th>時間ノード</th><th>重大事件</th></tr></thead><tbody><tr><td>-10000年</td><td>アンカーメカニズムが初めて発見され、発見者がこれを「アンカー」と命名し、系統的な研究を開始する</td></tr><tr><td>-9000年</td><td>初の人工アンカーが成功裏に構築され、アンカーが人為的に構築・維持できることが証明される</td></tr><tr><td>-8000年</td><td>アンカー技術が小範囲で伝播し始め、最初のアンカー修練者が出現する</td></tr><tr><td>-7000年</td><td>アンカーが跨位面接続の基準として使用できることが発見され、初の記録されたアンカー補助位面穿梭が成功する</td></tr><tr><td>-6000年</td><td>共生思想とアンカー技術が結合し始め、最初の「アンカー共生」の理論文献が问世する</td></tr><tr><td>-5000年</td><td>初のアンカーを基礎とする共生型城邦が樹立され、共生体系の実行可能性が証明される</td></tr><tr><td>-4000年</td><td>略奪式文明が共生型城邦に対して攻撃を発動し、共生城邦がアンカー技術によって成功裏に防御する</td></tr><tr><td>-3000年</td><td>共生思想が複数の星域で伝播し、ますます多くの文明が共生転型を試み始める</td></tr><tr><td>-2000年</td><td>初の「万族共生大会」が開催され、数十の種族の代表が共同で共生文明の未来を討論する</td></tr><tr><td>-1000年</td><td>アンカー技術と共生思想がすでに統一文明を樹立する条件を備え、共生体系確立期が開始される</td></tr></tbody></table><h2 id="五、共生体系確立期-1000年から-100年" tabindex="-1">五、共生体系確立期（-1000年から-100年） <a class="header-anchor" href="#五、共生体系確立期-1000年から-100年" aria-label="Permalink to &quot;五、共生体系確立期（-1000年から-100年）&quot;">​</a></h2><p>共生体系確立期はアンカー共生文明の制度枠組みが無から有へと至る重要な時期である。</p><table tabindex="0"><thead><tr><th>時間ノード</th><th>重大事件</th></tr></thead><tbody><tr><td>-1000年</td><td>共生憲法起草委員会が成立し、根本大法の起草を開始する</td></tr><tr><td>-950年</td><td>『共生憲法』草案が完成し、万族の意見を広く求め始める</td></tr><tr><td>-900年</td><td>『共生憲法』が全民公投を経て可決され、正式に発効し、アンカー共生文明の樹立が宣言される</td></tr><tr><td>-850年</td><td>アンカー議事会、共生執行委員会、共生法院の三大機構が正式に成立し運営される</td></tr><tr><td>-800年</td><td>聯産承包メカニズムが全国範囲で推進され始める</td></tr><tr><td>-700年</td><td>『共生労働法』『消費者保護法』などの基本法律が相次いで公布される</td></tr><tr><td>-600年</td><td>教育、医療、住宅、環境、独占禁止の五部配套法がすべて公布実施される</td></tr><tr><td>-500年</td><td>三百套本源修練体系の発掘と整理作業が正式に起動される</td></tr><tr><td>-400年</td><td>最初の五十套本源修練体系が整理と検証を完成する</td></tr><tr><td>-300年</td><td>倍増果実の技術化応用が突破を取得し、百倍推演増幅技術が成熟する</td></tr><tr><td>-200年</td><td>三百套体系がすべて整理を完成し、最後の安全検証段階に入る</td></tr><tr><td>-100年</td><td>三百套本源修練体系の全面的開放条件が成熟し、開放期に入る</td></tr></tbody></table><h2 id="六、三百套体系開放期-100年から-50年" tabindex="-1">六、三百套体系開放期（-100年から-50年） <a class="header-anchor" href="#六、三百套体系開放期-100年から-50年" aria-label="Permalink to &quot;六、三百套体系開放期（-100年から-50年）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>時間ノード</th><th>重大事件</th></tr></thead><tbody><tr><td>-100年</td><td>三百套本源修練体系が正式に全宇宙の衆生に無料で開放される</td></tr><tr><td>-90年</td><td>修練者数が十年間で百倍増加し、「人人有路」が初步的に実現される</td></tr><tr><td>-80年</td><td>本源三基（推演迭代、生命循環、空間法則調度）が最も人気のある体系となる</td></tr><tr><td>-70年</td><td>新体系を通じて修練し高位に達した最初の修練者が出現し、体系の有効性が証明される</td></tr><tr><td>-60年</td><td>導師ネットワークが全面的に構築され、高級修練者が初級修練者を指導する法的義務を履行し始める</td></tr><tr><td>-50年</td><td>全民修練レベルが大幅に向上し、20%活性化戦略の条件が成熟する</td></tr></tbody></table><h2 id="七、20-活性化戦略期-50年から元年" tabindex="-1">七、20%活性化戦略期（-50年から元年） <a class="header-anchor" href="#七、20-活性化戦略期-50年から元年" aria-label="Permalink to &quot;七、20%活性化戦略期（-50年から元年）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>時間ノード</th><th>重大事件</th></tr></thead><tbody><tr><td>-50年</td><td>20%活性化戦略が正式に起動され、目標は50年以内に20%の衆生を活性化して位面至高強者とすること</td></tr><tr><td>-40年</td><td>最初の位面至高強者が誕生し、活性化率が5%に達する</td></tr><tr><td>-30年</td><td>活性化率が10%に達し、位面至高強者がアンカー維持の中で核心的な役割を発揮し始める</td></tr><tr><td>-20年</td><td>活性化率が15%に達し、宇宙全体の修練レベルが質的な飛躍を実現する</td></tr><tr><td>-10年</td><td>活性化率が18%に達し、戦略目標に接近する</td></tr><tr><td>元年</td><td>活性化率が20.3%に達し、20%活性化戦略が円満に完成し、アンカー共生文明が新紀元に入る</td></tr></tbody></table><h2 id="八、首次昇維紀元-元年から100年" tabindex="-1">八、首次昇維紀元（元年から100年） <a class="header-anchor" href="#八、首次昇維紀元-元年から100年" aria-label="Permalink to &quot;八、首次昇維紀元（元年から100年）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>時間ノード</th><th>重大事件</th></tr></thead><tbody><tr><td>元年</td><td>共生文明が正式に昇維紀元に入ることを宣言し、四階段昇維路径の第一階段（現実築基）が完成する</td></tr><tr><td>20年</td><td>第二階段（科技賦能）が全面的に推進され、修練法則と技術工程が深度的に融合する</td></tr><tr><td>40年</td><td>複製鏡技術、隔離空間技術が工程化量産を実現し、跨位面考古が規模化時代に入る</td></tr><tr><td>60年</td><td>最初の意識昇維類修練者が高階に達し、第三階段（意識進化）が開始される</td></tr><tr><td>80年</td><td>意識域のインフラ建設が完成し、意識迁移技術が初步的に成熟する</td></tr><tr><td>100年</td><td>初の段階的昇維が成功し、共生文明全体が半個次元レベル向上する</td></tr></tbody></table><h2 id="九、万族共和紀元-100年から500年" tabindex="-1">九、万族共和紀元（100年から500年） <a class="header-anchor" href="#九、万族共和紀元-100年から500年" aria-label="Permalink to &quot;九、万族共和紀元（100年から500年）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>時間ノード</th><th>重大事件</th></tr></thead><tbody><tr><td>100年</td><td>万族共和が正式に成立を宣言し、すべての知的種族が共生文明枠組み内で平等な連合を実現する</td></tr><tr><td>150年</td><td>万族名録の編纂が完成し、すべての既知の知的種族が収録される</td></tr><tr><td>200年</td><td>跨種族通婚と文化融合が常態となり、新たな混合種族が出現し始める</td></tr><tr><td>300年</td><td>万族共同言語の普及が完成し、跨種族交流の障壁が基本的に解消される</td></tr><tr><td>400年</td><td>万族文化が大繁栄し、各民族の伝統文化が共生枠組み内で保護・発展される</td></tr><tr><td>500年</td><td>万族共和が成熟期に入り、跨位面探索の条件が全面的に成熟する</td></tr></tbody></table><h2 id="十、跨位面探索紀元-500年から2000年" tabindex="-1">十、跨位面探索紀元（500年から2000年） <a class="header-anchor" href="#十、跨位面探索紀元-500年から2000年" aria-label="Permalink to &quot;十、跨位面探索紀元（500年から2000年）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>時間ノード</th><th>重大事件</th></tr></thead><tbody><tr><td>500年</td><td>大規模な跨位面探索計画が正式に起動され、位面管理局が成立する</td></tr><tr><td>600年</td><td>探知された位面が千個を超え、位面座標総庫が初步的に建成される</td></tr><tr><td>800年</td><td>複製鏡異地考古方案が全面的に成熟し、跨位面考古が黄金時代に入る</td></tr><tr><td>1000年</td><td>時間遡及技術が突破を取得し、先観測後有限干渉準則が正式に確立される</td></tr><tr><td>1200年</td><td>探知された位面が十万個を超え、数十個の位面文明と外交関係が樹立される</td></tr><tr><td>1500年</td><td>跨位面倫理準則が全面的に実施され、文明間交流が規範化時代に入る</td></tr><tr><td>1800年</td><td>時間悖論防控メカニズムが完全に成熟し、時間遡及考古が規模化を実現する</td></tr><tr><td>2000年</td><td>跨位面探索が輝かしい成果を取得し、星間共生時代の条件が全面的に成熟する</td></tr></tbody></table><h2 id="十一、星間共生時代-2000年から未来" tabindex="-1">十一、星間共生時代（2000年から未来） <a class="header-anchor" href="#十一、星間共生時代-2000年から未来" aria-label="Permalink to &quot;十一、星間共生時代（2000年から未来）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>時間ノード</th><th>重大事件</th></tr></thead><tbody><tr><td>2000年</td><td>星間共生時代が正式に開啓され、第四階段（星間共生）が全面的に推進される</td></tr><tr><td>2500年（展望）</td><td>宇宙級アンカーネットワークが初步的に建成され、探知されたすべての位面をカバーする</td></tr><tr><td>3000年（展望）</td><td>跨位面共生体系が成熟し、万族が宇宙範囲内で真の共生を実現する</td></tr><tr><td>5000年（展望）</td><td>宇宙全体の昇維が完成し、恒元宙がより高い次元の存在状態に入る</td></tr><tr><td>未来（展望）</td><td>アンカー共生文明が宇宙の外への探索を継続し、共生理念をより広大な存在に伝播する</td></tr></tbody></table><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>編年史簡表はアンカー共生文明が蒙昧から覚醒へ、弱小から強大へ、本位面から全宇宙へと至る奮闘の叙事詩である。各紀元の交替は、共生理念が略奪理念に勝利し、文明進歩が野蛮衰退に勝利した証人である。歴史は過去の塵埃ではなく、未来の種子である——この歴史を理解することは、共生文明がどこから来てどこへ行くのかを理解することである。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>70-紀元区分総表</li><li>72-アンカー覚醒紀元</li><li>79-星間共生時代展望</li></ul>',32)])])}const q=d(h,[["render",l]]);export{u as __pageData,q as default};
